<!doctype html><html lang="<?php echo snap_escape_attr($view['site']['language']); ?>" dir="<?php echo snap_escape_attr($view['site']['direction']); ?>"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?php echo snap_escape_html($view['response']['page_title'] ?? $view['site']['site_name']); ?></title><link rel="stylesheet" href="<?php echo snap_escape_url($view['site']['skin_style_url']); ?>"><?php echo snap_render_html($view['site']['skin_custom_style'] ?? ''); ?><?php echo snap_render_html($view['site']['skin_presentation']['style'] ?? ''); ?></head><body class="slickr-v2">
<header class="sl-masthead"><div class="sl-cover"><?php if (!empty($view['site']['cover_url'])): ?><img class="sl-cover-img" src="<?php echo snap_escape_url($view['site']['cover_url']); ?>" alt=""><?php endif; ?><div class="sl-cover-scrim"></div><div class="sl-cover-profile"><div class="sl-profile-inner"><?php if (!empty($view['site']['avatar_url'])): ?><img class="sl-profile-avatar sl-profile-avatar--zoom" src="<?php echo snap_escape_url($view['site']['avatar_url']); ?>" alt=""><?php else: ?><span class="sl-profile-avatar"><span class="sl-profile-avatar-initials"><?php echo snap_escape_html($view['site']['site_name']); ?></span></span><?php endif; ?><div class="sl-profile-info"><h1 class="sl-profile-name"><?php echo snap_escape_html($view['site']['site_name']); ?></h1><?php if (!empty($view['site']['tagline'])): ?><p class="sl-profile-tagline"><?php echo snap_escape_html($view['site']['tagline']); ?></p><?php endif; ?><p class="sl-profile-stats"><?php echo snap_escape_html($view['response']['photo_count'] ?? ''); ?> photos</p></div></div></div></div><nav class="sl-profile-tabs"><div class="sl-tabs-inner"><?php echo snap_render_html(snap_render_component('navigation',['items'=>$view['response']['navigation'] ?? []])); ?></div></nav></header>
<?php if (($view['response']['kind'] ?? '') === 'landing' || ($view['response']['kind'] ?? '') === 'archive' || ($view['response']['kind'] ?? '') === 'hashtag'): ?><main class="sl-landing-stream"><div id="justified-grid" class="sl-archive-grid h-feed"><?php foreach (($view['response']['items'] ?? []) as $item): ?><a class="justified-item" href="<?php echo snap_escape_url($item['url'] ?? snap_route_url('photo',['slug'=>$item['img_slug'] ?? ''])); ?>" title="<?php echo snap_escape_attr($item['img_title'] ?? ''); ?>"><?php if (!empty($item['img_thumb_aspect']) || !empty($item['img_file'])): ?><?php echo snap_render_html(snap_render_component('image',['url'=>$item['img_thumb_aspect'] ?? $item['img_file'],'alt'=>$item['img_alt'] ?? $item['img_title'] ?? ''])); ?><?php endif; ?><span class="justified-item-overlay"><span class="justified-item-title"><?php echo snap_escape_html($item['img_title'] ?? ''); ?></span></span></a><?php endforeach; ?><?php if (empty($view['response']['items'])): ?><div class="sl-no-photos">No photographs yet.</div><?php endif; ?></div></main>
<?php elseif (($view['response']['kind'] ?? '') === 'photo' || ($view['response']['kind'] ?? '') === 'post' || ($view['response']['kind'] ?? '') === 'collection'): ?><main class="sl-single-flow h-entry"><div class="sl-main-column"><h1 class="sl-photo-title p-name"><?php echo snap_escape_html($view['response']['item']['img_title'] ?? $view['response']['item']['title'] ?? ''); ?></h1><div id="sl-photobox" class="sl-photo-wrap"><?php if (!empty($view['response']['item']['img_file']) || !empty($view['response']['item']['featured_image_path'])): ?><?php echo snap_render_html(snap_render_component('image',['url'=>$view['response']['item']['img_file'] ?? $view['response']['item']['featured_image_path'],'alt'=>$view['response']['item']['img_alt'] ?? $view['response']['item']['img_title'] ?? '','class'=>'sl-image post-image u-photo'])); ?><?php endif; ?></div><?php if (!empty($view['site']['skin_presentation']['slickr']['show_description'])): ?><div class="sl-description-block e-content"><?php echo snap_render_html($view['response']['item']['content'] ?? $view['response']['item']['description'] ?? $view['response']['item']['img_description'] ?? ''); ?></div><?php endif; ?><?php if (!empty($view['response']['comments'])): ?><div class="sl-comments-region"><?php echo snap_render_html(snap_render_component('comments',['items'=>$view['response']['comments']])); ?></div><?php endif; ?></div><aside class="sl-sidebar"><?php if (!empty($view['site']['skin_presentation']['slickr']['show_exif']) && !empty($view['response']['item']['exif'])): ?><div class="sl-sidebar-block"><table class="sl-metadata-table"><?php foreach ($view['response']['item']['exif'] as $label=>$value): ?><tr><th><?php echo snap_escape_html($label); ?></th><td><?php echo snap_escape_html($value); ?></td></tr><?php endforeach; ?></table><?php if (!empty($view['site']['skin_presentation']['slickr']['show_geo']) && !empty($view['response']['item']['geo_url'])): ?><div class="sl-geo-routing"><a href="<?php echo snap_escape_url($view['response']['item']['geo_url']); ?>" target="_blank" rel="noopener">View on map</a></div><?php endif; ?></div><?php endif; ?><?php if (!empty($view['site']['skin_presentation']['slickr']['show_provenance']) && (!empty($view['response']['item']['img_source_url']) || !empty($view['response']['item']['img_source_file']))): ?><div class="sl-sidebar-block sl-provenance">Imported from <?php if (!empty($view['response']['item']['img_source_url'])): ?><a href="<?php echo snap_escape_url($view['response']['item']['img_source_url']); ?>" rel="noopener">Flickr</a><?php else: ?><code><?php echo snap_escape_html($view['response']['item']['img_source_file']); ?></code><?php endif; ?></div><?php endif; ?></aside></main>
<?php elseif (($view['response']['kind'] ?? '') === 'page'): ?><main class="static-content"><h1 class="static-page-title"><?php echo snap_escape_html($view['response']['item']['title'] ?? ''); ?></h1><?php echo snap_render_html($view['response']['item']['content'] ?? ''); ?></main><?php else: ?><main class="sl-no-photos"><h1>Not found</h1></main><?php endif; ?>
<footer id="system-footer"><div class="footer-metadata-bar"><p><?php echo snap_escape_html($view['site']['site_name']); ?></p></div></footer><?php echo snap_render_html(snap_render_component('registered-assets',['assets'=>$view['site']['registered_assets'] ?? []])); ?><?php echo snap_render_html($view['site']['owner_custom_code'] ?? ''); ?></body></html>


